const invoiceView={provider:'',from:'2026-05-01',to:'2026-10-31',query:'',document:'',page:0,selectedId:null};

function invoiceScope(){
  const q=AC.normalize(invoiceView.query),doc=AC.normalize(invoiceView.document);
  return (state.invoices?.records||[]).filter(r=>(!invoiceView.provider||r.proveedor===invoiceView.provider)&&
    (!invoiceView.from||r.fecha>=invoiceView.from)&&(!invoiceView.to||r.fecha<=invoiceView.to)&&
    (!q||AC.normalize([r.producto,r.proveedor,r.documento].join(' ')).includes(q))&&
    (!doc||AC.normalize(r.documento).includes(doc)));
}

function invoiceExport(rows){
  const matrix=[['fecha','proveedor','factura','medicamento','cantidad','unidad','precio_envase_con_igv','importe_linea_con_igv','unidades_por_envase','unidades_totales','costo_por_unidad','criterio','fuente'],...rows.map(r=>[r.fecha,r.proveedor,r.documento,r.producto,r.cantidad,r.um,r.precio_unitario,r.importe_total,r.unidades_caja,r.unidades_totales,r.costo_unidad,r.metodo_deteccion,r.fuente])];
  downloadWorkbook('historico_facturas_actualizado.xlsx',matrix,'Facturas',[['Criterio','Valor'],['Periodo disponible',`${state.invoices.meta.from} a ${state.invoices.meta.to}`],['Importes nuevos','Las facturas electrónicas usan el valor de línea más IGV informado en el XML UBL.'],['Presentaciones','ML, G/GR y DOSIS son envases completos; tabletas, cápsulas, ampollas, sobres y jeringas se dividen cuando la cantidad es explícita.']]);
}

function invoiceDetail(row){
  if(!row)return '';
  const preview=row.pdf_url?`<div class="invoice-pdf">${row.pdf_preview_url?`<a href="${esc(row.pdf_url)}" target="_blank" rel="noopener"><img src="${esc(row.pdf_preview_url)}" alt="Primera página de la factura ${esc(row.documento)}"></a>`:`<iframe src="${esc(row.pdf_url)}#view=FitH" title="PDF de la factura ${esc(row.documento)}"></iframe>`}<div class="invoice-pdf-actions"><span>Vista del comprobante original</span><a class="btn secondary" href="${esc(row.pdf_url)}" target="_blank" rel="noopener">Abrir PDF</a></div></div>`:`<div class="invoice-pdf-missing"><b>PDF no disponible</b><span>Esta compra conserva sus datos históricos o XML, pero no se encontró un PDF asociado.</span></div>`;
  return `<article class="card invoice-detail"><div class="card-header"><div><h3>${esc(row.producto)}</h3><p>${esc(row.proveedor)} · <span class="mono">${esc(row.documento)}</span></p></div><button class="icon-btn" id="closeInvoiceDetail" aria-label="Cerrar detalle">×</button></div><div class="invoice-detail-grid"><div><div class="criteria-grid"><div><b>Compra</b><p>${dateFmt(row.fecha)} · ${quantity(row.cantidad)} ${esc(row.um||'unid.')}</p></div><div><b>Precio del envase</b><p>${money(row.precio_unitario)}</p></div><div><b>Presentación</b><p>${row.unidades_caja?quantity(row.unidades_caja)+' unidad(es) vendibles':'Pendiente de confirmar'}</p></div><div><b>Costo por unidad</b><p>${preciseMoney(row.costo_unidad)}</p></div></div><div class="cost-note"><b>Criterio:</b> ${esc(row.metodo_deteccion||'Sin criterio disponible')}<br><b>Fuente:</b> ${esc(row.fuente||'—')}</div></div>${preview}</div></article>`;
}

function renderInvoices(){
  const data=state.invoices;if(!data)return content.innerHTML='<div class="empty"><b>No se cargó el histórico de facturas</b>Regenera dist/invoices.json.</div>';
  const rows=invoiceScope().sort((a,b)=>b.fecha.localeCompare(a.fecha)||String(b.documento).localeCompare(String(a.documento))),documents=new Set(rows.map(r=>r.documento)),products=new Set(rows.map(r=>AC.normalize(r.producto))),total=rows.reduce((sum,r)=>sum+(r.importe_total||0),0),pages=Math.max(1,Math.ceil(rows.length/50));invoiceView.page=Math.min(invoiceView.page,pages-1);const page=rows.slice(invoiceView.page*50,(invoiceView.page+1)*50),selected=rows.find(r=>r.id===invoiceView.selectedId);
  content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">FACTURAS Y MEDICAMENTOS</p><h2>Todas las compras en una sola vista</h2><p>Consulta mayo–octubre sin separar la base anterior de las facturas recientes. Filtra por medicamento, factura, proveedor o fecha.</p></div><div class="purchase-actions"><span class="pill">Actualizado al ${dateFmt(data.meta.to)}</span><button class="btn secondary" id="exportInvoices">Exportar Excel</button></div></div>
    <section class="kpis">${kpi('▤',quantity(rows.length),'Líneas encontradas','según filtros')}${kpi('⌑',quantity(documents.size),'Facturas','sin duplicar')}${kpi('✺',quantity(products.size),'Medicamentos','descripciones distintas')}${kpi('S/',money(total),'Compras','importe de líneas')}</section>
    <div class="assumption">La vista abre con todo el periodo mayo–octubre. Haz clic en una fila marcada “Ver PDF” para consultar el comprobante; “Sin PDF” significa que el registro existe, pero el dashboard anterior no tenía ese archivo asociado.</div>
    <div class="analytics-filters invoice-filters"><label>Desde<input id="invoiceFrom" type="date" value="${esc(invoiceView.from)}"></label><label>Hasta<input id="invoiceTo" type="date" value="${esc(invoiceView.to)}"></label><label>Proveedor<select id="invoiceProvider"><option value="">Todos</option>${data.providers.map(p=>`<option ${invoiceView.provider===p.provider?'selected':''}>${esc(p.provider)}</option>`).join('')}</select></label><label>Nº de factura<input id="invoiceDocument" value="${esc(invoiceView.document)}" placeholder="Ej. F100-879558"></label><label class="analytics-search">Medicamento<input id="invoiceQuery" type="search" value="${esc(invoiceView.query)}" placeholder="Nombre, principio activo o concentración…"></label><button class="btn secondary" id="invoiceClear">Limpiar</button></div>
    <div class="table-wrap"><table class="data-table purchase-table"><thead><tr><th>Fecha</th><th>Proveedor</th><th>Factura</th><th>Medicamento</th><th>Cantidad</th><th>Precio envase</th><th>Importe</th><th>Unid./envase</th><th>Costo/unidad</th><th>Comprobante</th></tr></thead><tbody>${page.map(r=>`<tr class="invoice-row ${invoiceView.selectedId===r.id?'selected':''}" data-invoice-id="${r.id}"><td>${dateFmt(r.fecha)}</td><td><b>${esc(r.proveedor)}</b></td><td class="mono">${esc(r.documento||'—')}</td><td>${esc(r.producto)}</td><td class="numeric">${quantity(r.cantidad)} ${esc(r.um||'')}</td><td class="numeric">${money(r.precio_unitario)}</td><td class="numeric">${money(r.importe_total)}</td><td class="numeric">${r.unidades_caja?quantity(r.unidades_caja):'<span class="tag bonus">Revisar</span>'}</td><td class="numeric"><b>${preciseMoney(r.costo_unidad)}</b></td><td><span class="tag ${r.pdf_url?'pdf':'calc'}">${r.pdf_url?'Ver PDF':'Sin PDF'}</span></td></tr>`).join('')||'<tr><td colspan="10">Sin facturas para estos filtros.</td></tr>'}</tbody></table></div>
    <div class="pagination"><span>${quantity(rows.length)} registros · página ${invoiceView.page+1} de ${pages}</span><div><button id="invoicePrev" ${invoiceView.page===0?'disabled':''}>←</button> <button id="invoiceNext" ${invoiceView.page===pages-1?'disabled':''}>→</button></div></div>${selected?invoiceDetail(selected):''}</div>`;
  for(const [id,key] of [['invoiceFrom','from'],['invoiceTo','to'],['invoiceProvider','provider']])$('#'+id).onchange=e=>{invoiceView[key]=e.target.value;invoiceView.page=0;invoiceView.selectedId=null;renderInvoices()};
  for(const [id,key] of [['invoiceQuery','query'],['invoiceDocument','document']])$('#'+id).oninput=e=>{const caret=e.target.selectionStart;invoiceView[key]=e.target.value;invoiceView.page=0;invoiceView.selectedId=null;renderInvoices();$('#'+id).focus();$('#'+id).setSelectionRange(caret,caret)};
  $('#invoiceClear').onclick=()=>{Object.assign(invoiceView,{provider:'',from:'',to:'',query:'',document:'',page:0,selectedId:null});renderInvoices()};
  $('#invoicePrev').onclick=()=>{invoiceView.page--;invoiceView.selectedId=null;renderInvoices()};$('#invoiceNext').onclick=()=>{invoiceView.page++;invoiceView.selectedId=null;renderInvoices()};
  $('#exportInvoices').onclick=()=>invoiceExport(rows);
  document.querySelectorAll('[data-invoice-id]').forEach(tr=>tr.onclick=()=>{invoiceView.selectedId=Number(tr.dataset.invoiceId);renderInvoices()});
  if($('#closeInvoiceDetail'))$('#closeInvoiceDetail').onclick=()=>{invoiceView.selectedId=null;renderInvoices()};
}
